mapper.select:
SELECT message_data FROM harness_conversation_history WHERE 
AND message_seq > #{startFrom}
AND message_seq <= #{upTo}
ORDER BY message_seq

SELECT EXISTS (
    SELECT 1 FROM harness_conversation_history WHERE  AND message_id = #{messageID}
) AS present

SELECT message_data FROM harness_conversation_history
WHERE  AND turn_uuid = #{turnUUID}
ORDER BY message_seq

SELECT summary, up_to_seq FROM harness_compaction_summaries WHERE 
AND up_to_seq <= #{upToSeq}
ORDER BY up_to_seq DESC LIMIT 1
